<template><section class="pro-panel"><div class="pro-section-head"><div><span class="eyebrow">Updates</span><h1>Notifications</h1><p>Prediction review, publishing and account updates appear here.</p></div><button class="ghost" @click="markAll">{{unread?'Mark all read':'All read'}}</button></div><div v-if="notifications.length" class="activity-list"><div v-for="n in notifications" :key="n._id" :class="['activity-item',{unread:!n.read}]" @click="read(n)"><span class="activity-dot"></span><div><b>{{n.title}}</b><p>{{n.message}}</p><small>{{formatDateTime(n.createdAt)}}</small></div></div></div><div v-else class="empty">No notifications yet.</div></section></template><script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../services/api';import{formatDateTime}from'../utils/formatters';const notifications=ref<any[]>([]),unread=ref(0);async function load(){try{const d=await api.get('/me/notifications');notifications.value=d.data||[];unread.value=d.unread||0}catch{}}async function read(n:any){if(n.read)return;try{await api.patch(`/me/notifications/${n._id}/read`,{});n.read=true;unread.value=Math.max(0,unread.value-1)}catch{}}async function markAll(){try{await api.patch('/me/notifications/read-all',{});notifications.value.forEach(n=>n.read=true);unread.value=0}catch{}}onMounted(load)</script>
